// SVG Chart 1: Monthly Evolution Bars with MoM pills and Secular Trendline
function renderMonthlyEvolutionSvg(monthlyData) {
  const width = 800;
  const height = 320;
  const padding = { top: 40, right: 30, bottom: 50, left: 60 };
  const chartW = width - padding.left - padding.right;
  const chartH = height - padding.top - padding.bottom;

  const maxVal = Math.max(...monthlyData.map(d => d.volume_quotes), 10);
  const yUpper = Math.ceil((maxVal * 1.15) / 25) * 25;

  const colWidth = chartW / monthlyData.length;
  const barWidth = 46;

  // Grid lines
  const gridSteps = 5;
  let gridSvg = '';
  for (let i = 0; i <= gridSteps; i++) {
    const val = Math.round((yUpper / gridSteps) * i);
    const y = padding.top + chartH - (val / yUpper) * chartH;
    gridSvg += `<line x1="${padding.left}" y1="${y}" x2="${width - padding.right}" y2="${y}" stroke="#E2E8F0" stroke-width="1" stroke-dasharray="3,3"/>`;
    gridSvg += `<text x="${padding.left - 10}" y="${y + 4}" font-size="11" font-family="-apple-system, sans-serif" fill="#64748B" text-anchor="end">${val}</text>`;
  }

  // Bars & labels
  let barsSvg = '';
  const trendPoints = [];

  monthlyData.forEach((d, i) => {
    const x = padding.left + i * colWidth + (colWidth - barWidth) / 2;
    const barH = (d.volume_quotes / yUpper) * chartH;
    const y = padding.top + chartH - barH;
    const centerX = x + barWidth / 2;
    trendPoints.push(`${centerX},${y}`);

    // Won quotes sub-bar
    const wonH = (d.won_quotes / yUpper) * chartH;
    const wonY = padding.top + chartH - wonH;

    barsSvg += `
      <rect x="${x}" y="${y}" width="${barWidth}" height="${barH}" rx="3" fill="#0072BC" />
      <rect x="${x}" y="${wonY}" width="${barWidth}" height="${wonH}" rx="2" fill="#059669" opacity="0.85" />
      <text x="${centerX}" y="${y - 8}" font-size="12" font-weight="700" font-family="-apple-system, sans-serif" fill="#081433" text-anchor="middle">${d.volume_quotes}</text>
      <text x="${centerX}" y="${height - padding.bottom + 20}" font-size="11" font-weight="600" font-family="-apple-system, sans-serif" fill="#1E293B" text-anchor="middle">${d.month_name.slice(0, 3)}</text>
    `;

    if (d.mom_growth_pct !== null) {
      const isPos = d.mom_growth_pct >= 0;
      const pillColor = isPos ? '#059669' : '#E11D48';
      const pillBg = isPos ? '#ECFDF5' : '#FEF2F2';
      const sign = isPos ? '+' : '';
      barsSvg += `
        <rect x="${centerX - 24}" y="${height - padding.bottom + 28}" width="48" height="16" rx="8" fill="${pillBg}" />
        <text x="${centerX}" y="${height - padding.bottom + 40}" font-size="9" font-weight="700" font-family="-apple-system, sans-serif" fill="${pillColor}" text-anchor="middle">${sign}${d.mom_growth_pct}%</text>
      `;
    }
  });

  const polylineSvg = `<polyline points="${trendPoints.join(' ')}" fill="none" stroke="#081433" stroke-width="2" stroke-dasharray="4,4"/>`;
  const nodesSvg = trendPoints.map(p => {
    const [px, py] = p.split(',');
    return `<circle cx="${px}" cy="${py}" r="4" fill="#FFFFFF" stroke="#081433" stroke-width="2"/>`;
  }).join('');

  return `
    <svg viewBox="0 0 ${width} ${height}" class="svg-chart" xmlns="http://www.w3.org/2000/svg">
      <rect width="100%" height="100%" fill="#FFFFFF" rx="6" />
      ${gridSvg}
      ${barsSvg}
      ${polylineSvg}
      ${nodesSvg}
      <g transform="translate(${width - 240}, 15)">
        <rect x="0" y="0" width="12" height="12" rx="2" fill="#0072BC"/>
        <text x="18" y="10" font-size="10" font-family="-apple-system, sans-serif" fill="#334155">Total Cotizaciones</text>
        <rect x="110" y="0" width="12" height="12" rx="2" fill="#059669"/>
        <text x="128" y="10" font-size="10" font-family="-apple-system, sans-serif" fill="#334155">Ganadas (Cerradas)</text>
      </g>
    </svg>
  `;
}

// SVG Chart 2: Modal Split Donut Chart
function renderModalSplitSvg(modalData) {
  const width = 480;
  const height = 300;
  const cx = 150;
  const cy = 150;
  const r = 90;
  const strokeW = 32;
  const circ = 2 * Math.PI * r;

  const total = modalData.reduce((acc, d) => acc + d.volume_quotes, 0);
  const colors = ['#0072BC', '#0284C7', '#134074', '#D97706', '#64748B'];

  let currentOffset = 0;
  let slicesSvg = '';
  let legendSvg = '';

  modalData.forEach((d, i) => {
    const fraction = total > 0 ? d.volume_quotes / total : 0;
    const dashLength = fraction * circ;
    const color = colors[i % colors.length];

    slicesSvg += `
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${strokeW}"
        stroke-dasharray="${dashLength} ${circ}" stroke-dashoffset="${-currentOffset}"
        transform="rotate(-90 ${cx} ${cy})"/>
    `;
    currentOffset += dashLength;

    const legY = 55 + i * 40;
    legendSvg += `
      <g transform="translate(300, ${legY})">
        <rect x="0" y="0" width="12" height="12" rx="2" fill="${color}" />
        <text x="18" y="10" font-size="11" font-weight="700" font-family="-apple-system, sans-serif" fill="#081433">${d.share_pct}%</text>
        <text x="65" y="10" font-size="11" font-family="-apple-system, sans-serif" fill="#334155">${d.label.split('(')[0].trim()}</text>
        <text x="18" y="24" font-size="10" font-family="-apple-system, sans-serif" fill="#64748B">${d.volume_quotes} cotiz. • USD ${d.avg_freight_usd.toLocaleString('es-AR')}</text>
      </g>
    `;
  });

  return `
    <svg viewBox="0 0 ${width} ${height}" class="svg-chart" xmlns="http://www.w3.org/2000/svg">
      <rect width="100%" height="100%" fill="#FFFFFF" rx="6" />
      ${slicesSvg}
      <text x="${cx}" y="${cy - 4}" font-size="24" font-weight="800" font-family="-apple-system, sans-serif" fill="#081433" text-anchor="middle">${total}</text>
      <text x="${cx}" y="${cy + 14}" font-size="9" font-weight="700" font-family="-apple-system, sans-serif" fill="#64748B" text-anchor="middle" letter-spacing="1">COTIZACIONES</text>
      ${legendSvg}
    </svg>
  `;
}

// SVG Chart 3: Top 15 Clients Horizontal Bars
function renderTopClientsSvg(clients) {
  const width = 800;
  const barHeight = 20;
  const gap = 8;
  const padding = { top: 30, right: 90, bottom: 20, left: 240 };
  const height = padding.top + padding.bottom + clients.length * (barHeight + gap);
  const chartW = width - padding.left - padding.right;

  const maxVal = Math.max(...clients.map(c => c.volume_quotes), 10);
  let barsSvg = '';

  clients.forEach((c, idx) => {
    const y = padding.top + idx * (barHeight + gap);
    const barW = (c.volume_quotes / maxVal) * chartW;
    const barColor = idx < 3 ? '#081433' : (idx < 7 ? '#0072BC' : '#0284C7');

    const clientLabel = c.client_name.length > 32 ? c.client_name.slice(0, 30) + '…' : c.client_name;

    barsSvg += `
      <text x="${padding.left - 12}" y="${y + 14}" font-size="11" font-weight="600" font-family="-apple-system, sans-serif" fill="#1E293B" text-anchor="end">${c.rank}. ${clientLabel}</text>
      <rect x="${padding.left}" y="${y}" width="${barW}" height="${barHeight}" rx="3" fill="${barColor}" />
      <text x="${padding.left + barW + 8}" y="${y + 14}" font-size="11" font-weight="700" font-family="-apple-system, sans-serif" fill="#081433">${c.volume_quotes} <tspan font-weight="400" font-size="10" fill="#64748B">(${c.share_pct}%)</tspan></text>
    `;
  });

  return `
    <svg viewBox="0 0 ${width} ${height}" class="svg-chart" xmlns="http://www.w3.org/2000/svg">
      <rect width="100%" height="100%" fill="#FFFFFF" rx="6" />
      ${barsSvg}
    </svg>
  `;
}

// SVG Chart 4: Executive Performance Grouped Horizontal Bars
function renderExecutivePerformanceSvg(executives) {
  const width = 800;
  const rowHeight = 28;
  const gap = 8;
  const padding = { top: 40, right: 125, bottom: 20, left: 205 };
  const execList = Array.isArray(executives) && executives.length > 0 ? executives : [];
  const height = padding.top + padding.bottom + (execList.length || 1) * (rowHeight + gap);
  const chartW = width - padding.left - padding.right;

  const maxVal = Math.max(...execList.map(e => e.total_quotes_managed || 0), 10);
  let rowsSvg = '';

  execList.forEach((e, idx) => {
    const y = padding.top + idx * (rowHeight + gap);
    const totalW = Math.max(((e.total_quotes_managed || 0) / maxVal) * chartW, 2);
    const wonW = (e.won_quotes || 0) > 0 ? Math.max(((e.won_quotes || 0) / maxVal) * chartW, 2) : 0;
    const shortRole = e.role ? e.role.split('/')[0].split('&')[0].split(',')[0].trim() : '';

    rowsSvg += `
      <text x="${padding.left - 12}" y="${y + 13}" font-size="10.5" font-weight="700" font-family="-apple-system, sans-serif" fill="#081433" text-anchor="end">${e.executive_name}</text>
      <text x="${padding.left - 12}" y="${y + 24}" font-size="8.5" font-family="-apple-system, sans-serif" fill="#64748B" text-anchor="end">${shortRole}</text>
      <rect x="${padding.left}" y="${y + 3}" width="${totalW}" height="16" rx="3" fill="#E2E8F0" />
      ${wonW > 0 ? `<rect x="${padding.left}" y="${y + 3}" width="${wonW}" height="16" rx="3" fill="#059669" />` : ''}
      <text x="${padding.left + totalW + 8}" y="${y + 15}" font-size="10" font-weight="700" font-family="-apple-system, sans-serif" fill="#081433">${(e.total_quotes_managed || 0).toLocaleString('es-AR')} <tspan font-weight="600" font-size="9" fill="#059669">(${e.win_rate_pct}% win)</tspan></text>
    `;
  });

  return `
    <svg viewBox="0 0 ${width} ${height}" class="svg-chart" xmlns="http://www.w3.org/2000/svg">
      <rect width="100%" height="100%" fill="#FFFFFF" rx="6" />
      <g transform="translate(${width - 280}, 15)">
        <rect x="0" y="0" width="12" height="12" rx="2" fill="#E2E8F0"/>
        <text x="18" y="10" font-size="10" font-family="-apple-system, sans-serif" fill="#334155">Total Cotizaciones</text>
        <rect x="135" y="0" width="12" height="12" rx="2" fill="#059669"/>
        <text x="153" y="10" font-size="10" font-family="-apple-system, sans-serif" fill="#334155">Ganadas / Cerradas</text>
      </g>
      ${rowsSvg}
    </svg>
  `;
}

